const csurf = require('csurf');

// Apply CSRF protection to state-changing operations
app.post('/users', csurf(), validateUserCreate, handleValidationErrors, ...);
app.put('/users/:id', csurf(), validateId, validateUserUpdate, handleValidationErrors, ...);
app.patch('/users/:id', csurf(), validateId, validateUserUpdate, handleValidationErrors, ...);
app.delete('/users/:id', csurf(), validateId, handleValidationErrors, ...);

