### 9. Insecure Password Handling

**Severity: HIGH**

The application comments acknowledge that passwords need to be hashed before storing, but no actual hashing is implemented. If passwords are ever added to the user model, they would be stored in plain text.

**OWASP Category**: A07:2021 - Identification and Authentication Failures

**Remediation**:
```javascript
const bcrypt = require('bcrypt');
const saltRounds = 12;

// Hash passwords before storage
const hashPassword = async (password) => {
  return await bcrypt.hash(password, saltRounds);
};

// Compare passwords for authentication
const comparePassword = async (password, hashedPassword) => {
  return await bcrypt.compare(password, hashedPassword);
};

// Validate password strength
const validatePasswordStrength = (password) => {
  if (password.length < 12) {
    return { valid: false, error: 'Password must be at least 12 characters' };
  }
  if (!/[A-Z]/.test(password)) {
    return { valid: false, error: 'Password must contain at least one uppercase letter' };
  }
  if (!/[a-z]/.test(password)) {
    return { valid: false, error: 'Password must contain at least one lowercase letter' };
  }
  if (!/[0-9]/.test(password)) {
    return { valid: false, error: 'Password must contain at least one number' };
  }
  if (!/[!@#$%^&*()_+\-=[\]{};':"\\|,.<>/?]/.test(password)) {
    return { valid: false, error: 'Password must contain at least one special character' };
  }
  return { valid: true };
};

// Apply during user creation
app.post('/users', validateUserCreate, handleValidationErrors, async (req, res, next) => {
  try {
    const { name, email, role = 'user', password } = req.body;

    // Validate password strength if provided
    if (password) {
      const passwordValidation = validatePasswordStrength(password);
      if (!passwordValidation.valid) {
        return res.status(400).json({ error: passwordValidation.error });
      }
    }

    // Hash password
    const hashedPassword = password ? await hashPassword(password) : null;

    // Store user with hashed password
    const result = await db.query(
      'INSERT INTO users (name, email, role, password_hash) VALUES ($1, $2, $3, $4) RETURNING *',
      [name.trim(), email.trim().toLowerCase(), role, hashedPassword]
    );

    res.status(201).json({
      message: 'User created successfully',
      user: { id: result.rows[0].id, name: result.rows[0].name, email: result.rows[0].email, role: result.rows[0].role },
    });
  } catch (error) {
    next(error);
  }
});
```

