```

### 5. Update app.js to be Secure

```javascript
// Add at the top of app.js for secrets management
require('dotenv').config();

// Validate required environment variables
const requiredEnvVars = [
  'JWT_SECRET',
  'NODE_ENV'
];

for (const envVar of requiredEnvVars) {
