**Recommendation**: Implement JWT-based authentication with proper middleware:

```javascript
// Add authentication middleware
const jwt = require('jsonwebtoken');
const authConfig = {
  SECRET_KEY: process.env.JWT_SECRET || 'your-secret-key-change-in-production',
  TOKEN_EXPIRY: '24h'
};

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Get Bearer token

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  jwt.verify(token, authConfig.SECRET_KEY, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

const authorizeRole = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

