require('dotenv').config();

// Validation middleware for secrets
const validateSecrets = () => {
  const requiredSecrets = ['JWT_SECRET'];

  for (const secret of requiredSecrets) {
    if (!process.env[secret]) {
      throw new Error(`Missing required secret: ${secret}`);
    }

    // Length requirements for sensitive secrets
    if (secret === 'JWT_SECRET' && process.env[secret].length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }
  }

  console.log('✓ All required secrets are present and valid');
};

validateSecrets();
```

#### 2. **For Production - Use a Secrets Manager**

**Option A: AWS Secrets Manager**
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Load secrets at startup
const loadSecrets = async () => {
