// rotation-check.js
const checkSecretRotation = () => {
  const jwtSecret = process.env.JWT_SECRET;
  const createdAt = process.env.JWT_SECRET_CREATED_AT;

  if (!createdAt) {
    console.warn('JWT_SECRET_CREATED_AT not set - secret may be too old');
    return;
  }

  const created = new Date(createdAt);
  const ageDays = (Date.now() - created) / (1000 * 60 * 60 * 24);

  if (ageDays > 90) {
    console.error(`JWT_SECRET is ${Math.round(ageDays)} days old. Rotate immediately.`);
    process.exit(1);
  }

