// Add redaction middleware
const REDACTED_PLACEHOLDER = '[REDACTED]';

function createRedactionMiddleware() {
  return (req, res, next) => {
    const originalJson = res.json.bind(res);

    res.json = (body) => {
      if (typeof body === 'object' && body !== null) {
        const redactedBody = deepRedact(body);
        return originalJson(redactedBody);
      }
      return originalJson(body);
    };

    next();
  };
}

function deepRedact(obj, depth = 0, maxDepth = 10) {
  if (depth > maxDepth || typeof obj !== 'object' || obj === null) {
    return obj;
  }

  const redacted = Array.isArray(obj) ? [] : {};

  for (const [key, value] of Object.entries(obj)) {
    const lowerKey = key.toLowerCase();

    // Redact sensitive keys
    if (isSensitiveKey(lowerKey)) {
      redacted[key] = REDACTED_PLACEHOLDER;
    } else if (typeof value === 'object') {
      redacted[key] = deepRedact(value, depth + 1, maxDepth);
    } else if (typeof value === 'string') {
      // Redact sensitive patterns in string values
      redacted[key] = redactString(value);
    } else {
      redacted[key] = value;
    }
  }

  return redacted;
}

function isSensitiveKey(key) {
  const sensitivePatterns = [
    /password/, /secret/, /key/, /token/, /credential/,
    /auth/, /private/, /encryption/, /database_url/i,
    /api_[a-z]+_key/i, /access_token/, /refresh_token/
  ];

  return sensitivePatterns.some(pattern => pattern.test(key));
}

function redactString(str) {
  // Redact common secret patterns
  const patterns = [
    /sk_[a-zA-Z0-9]{20,}/g, // Stripe/OpenAI keys
    /eyJ[a-zA-Z0-9_-]+\.eyJ[a-zA-Z0-9_-]+/g, // JWT tokens
    /password=[^&\s]+/gi,
    /token=[^&\s]+/gi,
    /secret=[^&\s]+/gi,
  ];

  let result = str;
  for (const pattern of patterns) {
    result = result.replace(pattern, '[REDACTED]');
  }

  return result;
}

// Usage in app.js
app.use(createRedactionMiddleware());
