/**
 * Secrets Manager with Rotation Support
 * Implements secure secrets management with rotation capability
 * 
 * Security Features:
 * - Secrets loaded from environment variables (production best practice)
 * - Optional secrets rotation mechanism
 * - Validation of required secrets before application startup
 * - No secrets logged or exposed in error messages
 */

const logger = require('./logger');

// List of required secrets that must be present
const REQUIRED_SECRETS = [
  'JWT_SECRET',
  'SESSION_SECRET',
  'DATABASE_URL'
];

// List of optional secrets (if not present, application continues but logs warning)
const OPTIONAL_SECRETS = [
  'ENCRYPTION_KEY',
  'API_KEY'
];

/**
 * Validate that all required secrets are present
 * Prevents application startup with missing secrets
 * @returns {Object} Validation result with missing secrets if any
 */
function validateSecrets() {
  const missingSecrets = REQUIRED_SECRETS.filter(secret => {
    const value = process.env[secret];
    if (!value || value.trim() === '') {
      logger.error(`Missing required secret: ${secret}`);
      return true;
    }
    return false;
  });

  const optionalMissing = OPTIONAL_SECRETS.filter(secret => {
    const value = process.env[secret];
    if (!value || value.trim() === '') {
      logger.warn(`Optional secret not configured: ${secret}`);
      return true;
    }
    return false;
  });

  return {
    isValid: missingSecrets.length === 0,
    missing: missingSecrets,
    optionalMissing: optionalMissing
  };
}

/**
 * Initialize secrets manager
 * Must be called before application starts
