/**
 * Logger module with security-conscious logging
 * Ensures secrets are never logged
 * Implements different log levels and formats
 */

const { createLogger, format, transports } = require('winston');
const { combine, timestamp, printf, colorize, error: errorFormat } = format;

// Custom format to prevent secret logging
const safeMessageFormat = printf(({ level, message, timestamp, ...metadata }) => {
  // Check if message contains potential secret references
  const secretPatterns = [
    /password/i,
    /secret/i,
    /token/i,
    /key/i,
    /credential/i
  ];

  const sanitizedMetadata = {};

  // Sanitize metadata to prevent accidental secret logging
  for (const [key, value] of Object.entries(metadata)) {
    // Don't log full error stacks in production
    if (key === 'stack' && process.env.NODE_ENV === 'production') {
      continue;
    }

    // Don't log error objects directly (they might contain sensitive data)
    if (key === 'error' && typeof value === 'object') {
      sanitizedMetadata[key] = { 
        message: value.message || 'Error details not logged for security',
        type: value.constructor.name 
      };
    } else {
      sanitizedMetadata[key] = value;
    }
  }

  let logMessage = message;

  // Check if the message itself might contain secrets
  for (const pattern of secretPatterns) {
    if (pattern.test(message)) {
      logMessage = '[SECURITY-SENSITIVE MESSAGE REDACTED]';
      break;
    }
  }

  return `${timestamp} [${level}] ${logMessage}${Object.keys(sanitizedMetadata).length > 0 ? ` ${JSON.stringify(sanitizedMetadata)}` : ''}`;
});

// Create logger instance
const logger = createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: combine(
    timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    errorFormat(),
    safeMessageFormat
  ),
  transports: [
    new transports.Console({
      format: combine(
        colorize(),
        safeMessageFormat
      )
    })
  ]
});

// Handle uncaught exceptions with secure logging
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception', {
    message: error.message,
    type: error.constructor.name,
    stack: process.env.NODE_ENV !== 'production' ? error.stack : undefined
  });

  // Don't exit immediately for debugging in development
  if (process.env.NODE_ENV !== 'development') {
    process.exit(1);
  }
});

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection', { reason: reason?.message || reason });
});

// Add security audit logging capability
logger.security = (message, metadata = {}) => {
  logger.info({ 
    level: 'security',
    message: `[SECURITY] ${message}`,
    ...metadata
  });
};

module.exports = logger;

