// WARNING: In production, restrict this endpoint to internal networks only
app.post('/admin/rotate-secret', async (req, res) => {
  try {
    // Verify admin access (authentication should be implemented)
    const authHeader = req.headers['authorization'];
    if (!authHeader) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    const { secretName } = req.body;
    if (!secretName) {
      return res.status(400).json({ error: 'Secret name is required' });
    }

    // Rotate the specified secret
    const result = await rotateSecret(secretName);

    if (result.status === 'completed') {
      logger.security(`Secret rotated successfully: ${secretName}`, {
        rotationId: result.rotationTimestamp
      });
      res.json(result);
    } else {
      res.status(500).json({
        error: 'Secret rotation failed',
        details: result
      });
    }
  } catch (error) {
    logger.error('Secret rotation error:', { error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Graceful shutdown handler
