#!/usr/bin/env node

/**
 * Secrets Rotation Script
 * 
 * Usage: node scripts/rotate-secrets.js <secret-name>
 * 
 * This script rotates a specific secret and provides tracking information
 * for your rotation spreadsheet. It does NOT expose actual secret values.
 */

const { rotateSecret, REQUIRED_SECRETS, OPTIONAL_SECRETS } = require('../src/secretsManager');
const logger = require('../src/logger');

// Parse command line arguments
const secretName = process.argv[2];

if (!secretName) {
  console.error('Usage: node scripts/rotate-secrets.js <secret-name>');
  console.error('\nAvailable secrets:');
  console.error('REQUIRED:');
  REQUIRED_SECRETS.forEach(secret => console.error(`  - ${secret}`));
  console.error('\nOPTIONAL:');
  OPTIONAL_SECRETS.forEach(secret => console.error(`  - ${secret}`));
  process.exit(1);
}

// Validate secret name
const validSecrets = [...REQUIRED_SECRETS, ...OPTIONAL_SECRETS];
if (!validSecrets.includes(secretName)) {
  console.error(`Error: Unknown secret "${secretName}"`);
  console.error('\nAvailable secrets:');
  console.error('REQUIRED:');
  REQUIRED_SECRETS.forEach(secret => console.error(`  - ${secret}`));
  console.error('\nOPTIONAL:');
  OPTIONAL_SECRETS.forEach(secret => console.error(`  - ${secret}`));
  process.exit(1);
}

// Execute rotation
console.log(`Initiating rotation for secret: ${secretName}`);
console.log('This may take a few seconds...\n');

rotateSecret(secretName)
  .then(result => {
    console.log('\nRotation Result:');
    console.log(`  Secret Name: ${result.secretName}`);
    console.log(`  Status: ${result.status}`);
    console.log(`  Timestamp: ${result.rotationTimestamp}`);
    console.log(`  Method: ${result.rotationMethod}`);

    if (result.status === 'completed') {
      console.log('\n✅ Secret rotation completed successfully!');
      console.log('\nUpdate your rotation tracking spreadsheet with:');
      console.log(`  - Secret Name: ${secretName}`);
      console.log(`  - Rotation Date: ${new Date().toISOString().split('T')[0]}`);
      console.log(`  - Status: Completed`);
      console.log(`  - Rotation ID: ${result.rotationTimestamp}`);
    } else {
      console.log('\n❌ Secret rotation failed!');
      if (result.error) {
        console.log(`  Error: ${result.error}`);
      }
      console.log('\nUpdate your rotation tracking spreadsheet with:');
      console.log(`  - Secret Name: ${secretName}`);
      console.log(`  - Rotation Date: ${new Date().toISOString().split('T')[0]}`);
      console.log(`  - Status: Failed`);
      console.log(`  - Notes: ${result.error}`);
    }

    // Exit with appropriate code
    process.exit(result.status === 'completed' ? 0 : 1);
  })
  .catch(error => {
    console.error('\n❌ Secret rotation failed with exception!');
    console.error(`Error: ${error.message}`);
    console.error('\nUpdate your rotation tracking spreadsheet with:');
    console.log(`  - Secret Name: ${secretName}`);
    console.log(`  - Rotation Date: ${new Date().toISOString().split('T')[0]}`);
    console.log(`  - Status: Error`);
    console.log(`  - Notes: ${error.message}`);
    process.exit(1);
  });

