  // login logic
});

// Implement progressive delays or account lockout policies
const loginAttempts = new Map();

const progressiveRateLimiter = (req, res, next) => {
  const ip = req.ip;
  const attempts = loginAttempts.get(ip) || 0;

  if (attempts >= 3) {
    const retryAfter = Math.min(300, attempts * 60); // Progressive delay, max 5 minutes
    res.set('Retry-After', retryAfter.toString());
    return res.status(429).json({ 
      error: 'Too many login attempts. Try again later.' 
    });
  }

  next();
};

